// Generated by scripts/sync-valuation.py from shared/valuation/happiness.js as rp-valuation-happiness.js; edit the shared source.
// Happiness penalty and celebration timing. Pure ES module: no game globals.
//
// The penalty is an explicit, configurable fraction of affected raw yields.
// A snapshot must say whether its bases are raw (penalty still to apply) or
// net (penalty already applied); the two are never mixed. Happiness itself is
// never an affected yield and is never priced at a fixed 8.

import {isFiniteNumber, scoreYields, normalizeWeights, DEFAULT_VALUATION_WEIGHTS} from './rp-valuation-weights.js';
import {normalizeHorizon, discountedRangeSum} from './rp-valuation-horizon.js';

export const DEFAULT_HAPPINESS_PENALTY = Object.freeze({
  cap: 0.8,         // maximum fraction lost; slope must be supplied by caller
  minMultiplier: 0 // effective yield never goes below this fraction of base
});

// Raw happiness math needs an explicit slope/cap from the game-data adapter.
// Guessing 0.02 (or any other value) is not allowed: missing data is
// not-estimated. A normalized result can be passed through unchanged.
export function normalizePenaltyConfig(value) {
  if (value && typeof value === 'object' && 'config' in value && 'status' in value) return value;
  if (value === undefined || value === null) {
    return Object.freeze({status: 'not-estimated', reason: 'penalty-config-required', config: null});
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    return Object.freeze({status: 'invalid', reason: 'penalty-config-object-required', config: null});
  }
  const source = value;
  if (source.slope === undefined || source.cap === undefined) {
    return Object.freeze({status: 'not-estimated', reason: 'penalty-slope-cap-required', config: null});
  }
  const slope = source.slope;
  const cap = source.cap;
  const minMultiplier = source.minMultiplier === undefined ? DEFAULT_HAPPINESS_PENALTY.minMultiplier : source.minMultiplier;
  if (!isFiniteNumber(slope) || slope < 0) return Object.freeze({status: 'invalid', reason: 'penalty-slope-non-negative-finite', config: null});
  if (!isFiniteNumber(cap) || cap < 0 || cap > 1) return Object.freeze({status: 'invalid', reason: 'penalty-cap-0-to-1', config: null});
  if (!isFiniteNumber(minMultiplier) || minMultiplier < 0 || minMultiplier > 1) return Object.freeze({status: 'invalid', reason: 'penalty-minMultiplier-0-to-1', config: null});
  return Object.freeze({status: 'estimated', config: Object.freeze({slope, cap, minMultiplier})});
}

// Penalty applies only in the negative happiness segment. Crossing zero
// truncates it naturally; the cap is applied before any yield multiplication.
export function happinessPenalty(happiness, config) {
  if (!isFiniteNumber(happiness)) return null;
  const normalized = normalizePenaltyConfig(config);
  if (normalized.status !== 'estimated') return null;
  if (happiness >= 0) return 0;
  return Math.min(normalized.config.cap, -happiness * normalized.config.slope);
}

export function effectiveYield(base, happiness, config) {
  if (!isFiniteNumber(base)) return null;
  const normalized = normalizePenaltyConfig(config);
  if (normalized.status !== 'estimated') return null;
  const penalty = happinessPenalty(happiness, normalized);
  if (penalty === null) return null;
  return base * Math.max(normalized.config.minMultiplier, 1 - penalty);
}

function normalizeAffected(affectedYields) {
  if (!affectedYields) return {status: 'missing', entries: [], missing: ['affectedYields'], invalid: []};
  const entries = [];
  const missing = [];
  const invalid = [];
  const push = (key, raw) => {
    if (key === 'happiness') {
      invalid.push({key, reason: 'happiness-is-not-a-penalized-yield'});
      return;
    }
    if (!['food', 'production', 'gold', 'science', 'culture', 'diplomacy'].includes(key)) {
      invalid.push({key, reason: 'unknown-yield'});
      return;
    }
    let beforeBase;
    let afterBase;
    if (Array.isArray(raw)) {
      [beforeBase, afterBase] = raw;
    } else if (raw && typeof raw === 'object') {
      beforeBase = raw.beforeBase ?? raw.before;
      afterBase = raw.afterBase ?? raw.after;
    } else {
      invalid.push({key, reason: 'base-values-required'});
      return;
    }
    if (afterBase === undefined) afterBase = beforeBase;
    if (!isFiniteNumber(beforeBase) || !isFiniteNumber(afterBase)) {
      missing.push({key, fields: ['beforeBase', 'afterBase']});
      return;
    }
    entries.push({key, beforeBase, afterBase});
  };
  if (Array.isArray(affectedYields)) {
    for (const item of affectedYields) {
      if (typeof item === 'string') {
        invalid.push({key: item, reason: 'base-values-required'});
        continue;
      }
      push(item?.key, item);
    }
  } else if (typeof affectedYields === 'object') {
    for (const [key, value] of Object.entries(affectedYields)) push(key, value);
  } else {
    invalid.push({key: null, reason: 'affectedYields-array-or-object'});
  }
  if (!entries.length) {
    if (invalid.length) return {status: 'invalid', reason: 'invalid-affected-yields', entries, missing, invalid};
    return {status: 'not-estimated', reason: missing.length ? 'affected-yield-bases-missing' : 'no-affected-yields', entries, missing, invalid};
  }
  if (missing.length) return {status: 'not-estimated', reason: 'affected-yield-bases-missing', entries, missing, invalid};
  if (invalid.length) return {status: 'invalid', reason: 'invalid-affected-yields', entries, missing, invalid};
  return {status: 'estimated', entries, missing, invalid};
}

// Actual before/after effective-output difference for one action.
// Required context: happiness before/after, basis, explicit affected yields,
// and finite bases for those yields. Without them the result is not estimated.
export function effectiveYieldImpact(input = {}) {
  const {
    happinessBefore,
    happinessAfter,
    basis,
    affectedYields,
    weights = DEFAULT_VALUATION_WEIGHTS,
    penalty = DEFAULT_HAPPINESS_PENALTY,
    penaltyByYield = {}
  } = input;

  if (!isFiniteNumber(happinessBefore) || !isFiniteNumber(happinessAfter)) {
    return Object.freeze({status: 'not-estimated', reason: 'happiness-before-after-required', benefit: null, missing: ['happinessBefore', 'happinessAfter']});
  }
  if (basis !== 'raw' && basis !== 'net') {
    return Object.freeze({status: 'not-estimated', reason: 'basis-raw-or-net-required', benefit: null, missing: ['basis']});
  }
  const affected = normalizeAffected(affectedYields);
  if (affected.invalid?.length) {
    return Object.freeze({status: 'invalid', reason: 'invalid-affected-yields', benefit: null, invalid: affected.invalid});
  }
  if (affected.status !== 'estimated') {
    return Object.freeze({status: 'not-estimated', reason: affected.reason, benefit: null, missing: affected.missing, invalid: affected.invalid});
  }
  const normalizedWeights = weights && weights.weights ? weights : normalizeWeights(weights);
  if (normalizedWeights.status === 'invalid') {
    return Object.freeze({status: 'invalid', reason: 'invalid-weights', benefit: null, invalid: normalizedWeights.invalid});
  }
  const weightsValue = normalizedWeights.weights;
  const contributions = {};
  const penalties = {};
  const effective = {};
  const missing = [];
  let benefit = 0;

  for (const {key, beforeBase, afterBase} of affected.entries) {
    const weight = weightsValue[key];
    if (!isFiniteNumber(weight)) {
      missing.push({key, field: 'weight'});
      continue;
    }
    let beforeEffective;
    let afterEffective;
    let beforePenalty = 0;
    let afterPenalty = 0;
    if (basis === 'net') {
      beforeEffective = beforeBase;
      afterEffective = afterBase;
    } else {
      const configInput = penaltyByYield[key] === undefined ? penalty : penaltyByYield[key];
      const config = normalizePenaltyConfig(configInput);
      if (config.status === 'not-estimated') {
        return Object.freeze({status: 'not-estimated', reason: `penalty-config-required:${key}`, benefit: null, missing: Object.freeze([`penalty:${key}`])});
      }
      if (config.status === 'invalid') {
        return Object.freeze({status: 'invalid', reason: `penalty-config-invalid:${key}`, benefit: null});
      }
      beforePenalty = happinessPenalty(happinessBefore, config);
      afterPenalty = happinessPenalty(happinessAfter, config);
      if (beforePenalty === null || afterPenalty === null) {
        return Object.freeze({status: 'invalid', reason: `penalty-evaluation-failed:${key}`, benefit: null});
      }
      beforeEffective = beforeBase * Math.max(config.config.minMultiplier, 1 - beforePenalty);
      afterEffective = afterBase * Math.max(config.config.minMultiplier, 1 - afterPenalty);
    }
    if (!isFiniteNumber(beforeEffective) || !isFiniteNumber(afterEffective)) {
      return Object.freeze({status: 'invalid', reason: `effective-yield-non-finite:${key}`, benefit: null});
    }
    const contribution = (afterEffective - beforeEffective) * weight;
    if (!isFiniteNumber(contribution)) {
      return Object.freeze({status: 'invalid', reason: `contribution-overflow:${key}`, benefit: null});
    }
    contributions[key] = contribution;
    penalties[key] = Object.freeze({before: beforePenalty, after: afterPenalty});
    effective[key] = Object.freeze({before: beforeEffective, after: afterEffective});
    benefit += contribution;
  }
  if (missing.length) {
    return Object.freeze({status: 'not-estimated', reason: 'missing-weights', benefit: null, missing, contributions: Object.freeze(contributions)});
  }
  if (!isFiniteNumber(benefit)) {
    return Object.freeze({status: 'invalid', reason: 'benefit-overflow', benefit: null, contributions: Object.freeze(contributions)});
  }
  return Object.freeze({
    status: 'estimated',
    benefit: benefit,
    benefitPerTurn: benefit,
    basis,
    penaltyApplied: basis === 'raw',
    contributions: Object.freeze(contributions),
    penalties: Object.freeze(penalties),
    effective: Object.freeze(effective),
    happinessBefore,
    happinessAfter,
    affectedYields: Object.freeze(affected.entries.map(entry => entry.key)),
    evidence: Object.freeze({
      basis,
      happinessBefore,
      happinessAfter,
      affectedYields: Object.freeze(affected.entries.map(entry => entry.key)),
      penalties: Object.freeze(penalties),
      effective: Object.freeze(effective),
      note: basis === 'net' ? 'bases already include happiness penalty; not applied twice' : 'penalty applied to raw bases only'
    })
  });
}

function normalizeCelebrationPlan(plan = {}) {
  if (!plan || typeof plan !== 'object' || Array.isArray(plan)) {
    return {status: 'not-estimated', reason: 'celebration-plan-required'};
  }
  if (plan.timeline !== undefined) {
    if (!Array.isArray(plan.timeline)) return {status: 'invalid', reason: 'celebration-timeline-array-required'};
    const turns = [];
    for (const item of plan.timeline) {
      if (!item || !Number.isInteger(item.turn) || !item.yields || typeof item.yields !== 'object') {
        return {status: 'invalid', reason: 'celebration-timeline-items-need-turn-and-yields'};
      }
      turns.push({turn: item.turn, yields: item.yields});
    }
    return {status: 'estimated', source: 'caller-timeline', predictedByCaller: true, timeline: turns};
  }
  for (const key of ['progress', 'threshold', 'happinessPerTurn', 'duration']) {
    if (!isFiniteNumber(plan[key]) && !(key === 'duration' && Number.isInteger(plan[key]))) {
      return {status: 'not-estimated', reason: `celebration-${key}-required`, missing: [key]};
    }
  }
  if (!Number.isInteger(plan.duration) || plan.duration <= 0) {
    return {status: 'invalid', reason: 'celebration-duration-positive-integer'};
  }
  if (!plan.effectYields || typeof plan.effectYields !== 'object') {
    return {status: 'not-estimated', reason: 'celebration-effect-yields-required', missing: ['effectYields']};
  }
  return {status: 'estimated', source: 'derived', predictedByCaller: false, ...plan};
}

export function celebrationTimeline(plan, {currentTurn, endTurn, discountRate = 0, weights = DEFAULT_VALUATION_WEIGHTS} = {}) {
  const normalized = normalizeCelebrationPlan(plan);
  if (normalized.status !== 'estimated') return Object.freeze({...normalized, value: null});
  const horizon = normalizeHorizon({currentTurn, endTurn, firstReceiptTurn: currentTurn + 1, discountRate});
  if (horizon.status === 'invalid') return Object.freeze({status: 'invalid', reason: horizon.reason, value: null});
  if (horizon.status === 'ended') return Object.freeze({status: 'ended', value: 0, receipts: 0, startTurn: null, endTurn, source: normalized.source});

  let startTurn = null;
  let activeTurns = 0;
  let value = 0;
  let effectValue = 0;

  if (normalized.source === 'caller-timeline') {
    const sorted = [...normalized.timeline].sort((a, b) => a.turn - b.turn);
    for (const item of sorted) {
      if (item.turn < horizon.startTurn || item.turn > endTurn) continue;
      const scored = scoreYields(item.yields, weights);
      if (scored.status === 'invalid') return Object.freeze({status: 'invalid', reason: `celebration-timeline-invalid:${item.turn}`, value: null});
      const turnValue = scored.score;
      if (startTurn === null) startTurn = item.turn;
      activeTurns++;
      effectValue += turnValue;
      const q = discountRate === 0 ? 1 : 1 / ((1 + discountRate) ** (item.turn - currentTurn));
      value += turnValue * q;
    }
    return Object.freeze({
      status: 'estimated',
      value,
      discountedValue: value,
      undiscountedValue: effectValue,
      startTurn,
      activeTurns,
      receipts: horizon.count,
      endTurn,
      source: normalized.source,
      predictedByCaller: true,
      evidence: Object.freeze({timeline: normalized.timeline, note: 'caller supplied forecast; only supplied turns count'})
    });
  }

  const {progress, threshold, happinessPerTurn, duration, effectYields} = normalized;
  const scoredEffect = scoreYields(effectYields, weights);
  if (scoredEffect.status === 'invalid') return Object.freeze({status: 'invalid', reason: 'celebration-effect-yields-invalid', value: null});
  if (!(scoredEffect.score > 0) && !(scoredEffect.score < 0)) {
    return Object.freeze({status: 'estimated', value: 0, discountedValue: 0, undiscountedValue: 0, startTurn: null, activeTurns: 0, receipts: horizon.count, endTurn, source: normalized.source, evidence: Object.freeze({note: 'celebration effect has zero value'})});
  }
  if (progress >= threshold) {
    startTurn = horizon.startTurn;
  } else if (happinessPerTurn <= 0) {
    startTurn = null;
  } else {
    const needed = Math.ceil((threshold - progress) / happinessPerTurn);
    startTurn = currentTurn + Math.max(1, needed);
  }
  if (startTurn === null || startTurn > endTurn) {
    return Object.freeze({status: 'never-within-horizon', value: 0, discountedValue: 0, undiscountedValue: 0, startTurn: null, activeTurns: 0, receipts: horizon.count, endTurn, source: normalized.source, predictedByCaller: false});
  }
  const lastActive = Math.min(endTurn, startTurn + duration - 1);
  activeTurns = lastActive - startTurn + 1;
  effectValue = scoredEffect.score * activeTurns;
  value = discountedRangeSum(scoredEffect.score, {currentTurn, endTurn: lastActive, firstReceiptTurn: startTurn, discountRate}) ?? null;
  if (value === null) return Object.freeze({status: 'invalid', reason: 'celebration-discount-failed', value: null});
  return Object.freeze({
    status: 'estimated',
    value,
    discountedValue: value,
    undiscountedValue: effectValue,
    startTurn,
    lastActiveTurn: lastActive,
    activeTurns,
    receipts: horizon.count,
    duration,
    effectValue: scoredEffect.score,
    endTurn,
    source: normalized.source,
    predictedByCaller: false,
    evidence: Object.freeze({progress, threshold, happinessPerTurn, duration, effectYields, activeTurns})
  });
}

// Compares two schedules of the same celebration. Only the actual schedule
// difference is returned: if both start at the same turn the delta is zero; a
// deadline clips both schedules; an earlier start counts only extra active
// turns, never the whole celebration again.
export function compareCelebration({before, after, currentTurn, endTurn, discountRate = 0, weights = DEFAULT_VALUATION_WEIGHTS} = {}) {
  const b = celebrationTimeline(before, {currentTurn, endTurn, discountRate, weights});
  const a = celebrationTimeline(after, {currentTurn, endTurn, discountRate, weights});
  if (b.status === 'invalid' || b.status === 'not-estimated' || a.status === 'invalid' || a.status === 'not-estimated') {
    return Object.freeze({status: 'not-estimated', reason: 'celebration-plan-incomplete', before: b, after: a, delta: null});
  }
  return Object.freeze({
    status: 'estimated',
    before: b,
    after: a,
    delta: a.value - b.value,
    onlyActualDifference: true,
    predictedByCaller: Boolean(b.predictedByCaller || a.predictedByCaller),
    evidence: Object.freeze({
      beforeStart: b.startTurn,
      afterStart: a.startTurn,
      beforeActiveTurns: b.activeTurns,
      afterActiveTurns: a.activeTurns,
      endTurn,
      note: 'delta is after schedule value minus before schedule value within the same horizon'
    })
  });
}
